@startuml

class Customer {
  + VATNumber : string
  + Name : string
  + PhoneNumber : string
  + Address : string
}

class Package {
  + IdentifierCode : string
  + Weight : float
  + IsUrgent : boolean
}

class DeliveryCenter {
  + Name : string
  + Address : string
}

class Courier {
  + VATNumber : string
  + Name : string
  + PhoneNumber : string
}

Customer "1" -- "0..*" Package : sends
Customer "1" -- "0..*" Package : receives
Customer "1" -- "1" DeliveryCenter : associated to
Package "0..*" -- "1" DeliveryCenter : delivered at
Package "0..*" -- "0..1" Courier : assigned to
Courier "0..*" -- "1" DeliveryCenter : works in

@enduml

